2006	/// Operators for which precedence must be defined.
2007	///
2008	/// Higher number -> higher precedence.
2009	/// See expression parsing for how these values are used.
2010	#[derive(Debug, Clone, Copy)]
2011	pub enum Precedence {
2012	    /// Member access operator `.` (highest precedence).
2013	    Period,
2014	    /// Postgres style type cast `::`.
2015	    DoubleColon,
2016	    /// Timezone operator (e.g. `AT TIME ZONE`).
2017	    AtTz,
2018	    /// Multiplication / Division / Modulo operators (`*`, `/`, `%`).
2019	    MulDivModOp,
2020	    /// Addition / Subtraction (`+`, `-`).
2021	    PlusMinus,
2022	    /// Bitwise `XOR` operator (`^`).
2023	    Xor,
2024	    /// Bitwise `AND` operator (`&`).
2025	    Ampersand,
2026	    /// Bitwise `CARET` (^) for some dialects.
2027	    Caret,
2028	    /// Bitwise `OR` / pipe operator (`|`).
2029	    Pipe,
2030	    /// `:` operator for json/variant access.
2031	    Colon,
2032	    /// `BETWEEN` operator.
2033	    Between,
2034	    /// Equality operator (`=`).
2035	    Eq,
2036	    /// Pattern matching (`LIKE`).
2037	    Like,
2038	    /// `IS` operator (e.g. `IS NULL`).
2039	    Is,
2040	    /// Other Postgres-specific operators.
2041	    PgOther,
2042	    /// Unary `NOT`.
2043	    UnaryNot,
2044	    /// Logical `AND`.
2045	    And,
2046	    /// Logical `OR` (lowest precedence).
2047	    Or,
2048	}
