2059	/// Returns the built in [`Dialect`] corresponding to `dialect_name`.
2060	///
2061	/// See [`Dialect`] documentation for an example.
2062	pub fn dialect_from_str(dialect_name: impl AsRef<str>) -> Option<Box<dyn Dialect>> {
2063	    let dialect_name = dialect_name.as_ref();
2064	    match dialect_name.to_lowercase().as_str() {
2065	        "generic" => Some(Box::new(GenericDialect)),
2066	        "mysql" => Some(Box::new(MySqlDialect {})),
2067	        "postgresql" | "postgres" => Some(Box::new(PostgreSqlDialect {})),
2068	        "hive" => Some(Box::new(HiveDialect {})),
2069	        "sqlite" => Some(Box::new(SQLiteDialect {})),
2070	        "snowflake" => Some(Box::new(SnowflakeDialect)),
2071	        "redshift" => Some(Box::new(RedshiftSqlDialect {})),
2072	        "mssql" => Some(Box::new(MsSqlDialect {})),
2073	        "clickhouse" => Some(Box::new(ClickHouseDialect {})),
2074	        "bigquery" => Some(Box::new(BigQueryDialect)),
2075	        "ansi" => Some(Box::new(AnsiDialect {})),
2076	        "duckdb" => Some(Box::new(DuckDbDialect {})),
2077	        "databricks" => Some(Box::new(DatabricksDialect {})),
2078	        "spark" | "sparksql" => Some(Box::new(SparkSqlDialect {})),
2079	        "oracle" => Some(Box::new(OracleDialect {})),
2080	        "teradata" => Some(Box::new(TeradataDialect {})),
2081	        _ => None,
2082	    }
2083	}
