'-' => {
    chars.next(); // consume the '-'

    match chars.peek() {
        Some('-') => {
            let mut is_comment = true;
            if self.dialect.requires_single_line_comment_whitespace() {
                is_comment = chars
                    .peekable
                    .clone()
                    .nth(1)
                    .is_some_and(char::is_whitespace);
