fn parse_stage_table_factor_rejected() {
    let sql = "SELECT * FROM @stage";
    assert_eq!(
        pg().parse_sql_statements(sql).unwrap_err(),
        ParserError::ParserError("Expected: identifier, found: @".to_string()),
    );
}

