use sqlparser::dialect::{PostgreSqlDialect, GenericDialect};
use sqlparser::parser::Parser;
use sqlparser::ast::*;

fn depth(sql: &str, d: &dyn sqlparser::dialect::Dialect) {
    let s = Parser::parse_sql(d, sql).unwrap();
    let q = match &s[0] { Statement::Query(q) => q, _ => panic!() };
    let e = match q.body.as_ref() { SetExpr::Select(sel) => match &sel.projection[0] {
        SelectItem::UnnamedExpr(e) => e, _ => panic!()
    }, _ => panic!() };
    fn shape(e: &Expr) -> String {
        match e {
            Expr::UnaryOp { op, expr } => format!("u{}({})", match op {UnaryOperator::Minus=>"-",UnaryOperator::Plus=>"+",_=>"?"}, shape(expr)),
            Expr::BinaryOp { left, op, right } => format!("({} {} {})", shape(left), op, shape(right)),
            Expr::Nested(x) => format!("N[{}]", shape(x)),
            Expr::Cast { expr, .. } => format!("cast({})", shape(expr)),
            Expr::CompoundFieldAccess { root, access_chain } => format!("{}{:?}", root, access_chain),
            Expr::Collate { expr, collation } => format!("collate({}, {})", shape(expr), collation),
            Expr::AtTimeZone { timestamp, time_zone } => format!("attz({}, {})", shape(timestamp), shape(time_zone)),
            other => format!("{other}"),
        }
    }
    println!("{sql:34} {}", shape(e));
}

fn main() {
    let pg = PostgreSqlDialect {};
    let g = GenericDialect {};
    for case in [
        "SELECT -2 ^ 2",
        "SELECT +a ^ b",
        "SELECT a ^ -b",
        "SELECT -a ^ b ^ c",
        "SELECT -items[1]::INT ^ 2",
        "SELECT -name COLLATE \"C\"",
        "SELECT -ts AT TIME ZONE 'UTC'",
        "SELECT -(a ^ b)",
        "SELECT - -a ^ b",
        "SELECT 3 - -a ^ b",
        "SELECT -a * b",
        "SELECT -a + b",
        "SELECT a - -b",
    ] {
        print!("PG: "); depth(case, &pg);
        print!("GN: "); depth(case, &g);
    }
}
EOF
