    // For example, the expression `a.b.c.foo(1,2,3)` should
    // represent a function called `a.b.c.foo`, rather than
    // a composite expression.
    if matches!(root, Expr::Identifier(_))
        && matches!(
            access_chain.last(),
            Some(AccessExpr::Dot(Expr::Function(_)))
