        Precedence::Caret => 22,
        Precedence::Pipe => 21,
        Precedence::Colon => 21,
        // "any other operator" -- `->`, `@>`, custom operators. PostgreSQL
        // places this row above `BETWEEN` / `LIKE` and below `+` / `-`
