/// (`::`, subscripts) and every binary operator, so that e.g. `-2 ^ 2` is
/// `(-2) ^ 2` while `-items[1]::INT ^ 2` puts the sign around the cast
/// but inside the power.
fn prefix_sign_precedence(&self) -> u8 {
    self.prec_value(Precedence::MulDivModOp)
}

