mkdir -p examples && cat > examples/zz_verify.rs <<'EOF'
use sqlparser::ast::*;
use sqlparser::dialect::{GenericDialect, PostgreSqlDialect};
use sqlparser::parser::Parser;

fn shape(e: &Expr) -> String {
    match e {
        Expr::UnaryOp { op, expr } => {
            let s = match op {
                UnaryOperator::Minus => "-",
                UnaryOperator::Plus => "+",
                _ => "?",
            };
            format!("{}({})", s, shape(expr))
        }
        Expr::BinaryOp { left, op, right } => {
            format!("({} {} {})", shape(left), op, shape(right))
        }
        Expr::Nested(x) => format!("N[{}]", shape(x)),
        Expr::Cast { expr, .. } => format!("cast({})", shape(expr)),
        Expr::CompoundFieldAccess { root, .. } => format!("{root}[sub]"),
        Expr::Collate { expr, collation } => format!("collate({}, {})", shape(expr), collation),
        Expr::AtTimeZone {
            timestamp,
            time_zone,
        } => format!("attz({}, {})", shape(timestamp), shape(time_zone)),
        other => format!("{other}"),
    }
}

fn main() {
    let pg = PostgreSqlDialect {};
    for sql in [
        "SELECT -2 ^ 2",
        "SELECT +a ^ b",
        "SELECT a ^ -b",
        "SELECT -a ^ b ^ c",
        "SELECT -items[1]::INT ^ 2",
        "SELECT -name COLLATE \"C\"",
        "SELECT -ts AT TIME ZONE 'UTC'",
        "SELECT -(a ^ b)",
        "SELECT - -a ^ b",
        "SELECT 3 - -a ^ b",
        "SELECT -a ^ -b ^ -c",
    ] {
        let s = Parser::parse_sql(&pg, sql).unwrap();
        let e = match &s[0] {
            Statement::Query(q) => match q.body.as_ref() {
                SetExpr::Select(sel) => match &sel.projection[0] {
                    SelectItem::UnnamedExpr(e) => e,
                    _ => panic!(),
                },
                _ => panic!(),
            },
            _ => panic!(),
        };
        println!("{sql:32} => {}\n        display: {}", shape(e), s[0]);
    }
    // errors
    for sql in ["SELECT -", "SELECT a ^ -", "SELECT -(a ^ )"] {
        println!("{sql:32} => ERR {}", Parser::parse_sql(&pg, sql).unwrap_err());
    }
    // generic unchanged sanity
    let s = Parser::parse_sql(&GenericDialect {}, "SELECT -2 ^ 2").unwrap();
    println!("generic -2 ^ 2 => {s}");
}
EOF
